package tw.aihankapps.timehut;

import android.app.Instrumentation;
import android.content.Context;
import android.content.Intent;
import android.net.ConnectivityManager;
import android.webkit.WebView;
import android.util.Base64;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.runner.lifecycle.ActivityLifecycleMonitorRegistry;
import androidx.test.runner.lifecycle.Stage;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.*;
import static org.junit.Assert.*;

/** Actual bridge/UIDT -> real Node/Multer2.4/SQLite, only synthetic provider/media. */
@RunWith(AndroidJUnit4.class)
public class AccountServerIntegrationTest {
    private Instrumentation instrumentation;private Context context;private WebView view;
    private JSONObject call(String method,JSONObject args)throws Exception{if(java.util.Arrays.asList("accountSignIn","accountRequest","accountSignOut","list","thumbnail","prepareUpload","enqueueUpload","enqueueDownload","cancel","retry","saveToPhotos").contains(method)&&!args.has("expectedGeneration")){JSONObject scope=AccountClient.bridgeStatus();args.put("expectedGeneration",scope.getString("generation"));if(!method.equals("accountSignIn"))args.put("expectedOwner",scope.opt("owner"));}String key="server_"+java.util.UUID.randomUUID().toString().replace("-","");instrumentation.runOnMainSync(()->view.evaluateJavascript("window.serverIntegrationCalls=window.serverIntegrationCalls||{};(async()=>{try{const r=await Capacitor.registerPlugin('TimehutTransfer')."+method+"("+args+");window.serverIntegrationCalls['"+key+"']={result:r||{}};}catch(e){window.serverIntegrationCalls['"+key+"']={error:String(e)};}})()",null));long deadline=System.currentTimeMillis()+15000;while(System.currentTimeMillis()<deadline){CountDownLatch latch=new CountDownLatch(1);String[] value={null};instrumentation.runOnMainSync(()->view.evaluateJavascript("JSON.stringify(window.serverIntegrationCalls&&window.serverIntegrationCalls['"+key+"']||null)",r->{value[0]=r;latch.countDown();}));assertTrue(latch.await(2,TimeUnit.SECONDS));if(value[0]!=null&&!value[0].equals("null")){Object decoded=new JSONTokener(value[0]).nextValue();if(decoded instanceof String&&!decoded.equals("null"))return new JSONObject((String)decoded);}Thread.sleep(50);}throw new AssertionError("Server integration bridge timeout");}
    private JSONObject success(String method,JSONObject args)throws Exception{JSONObject response=call(method,args);assertFalse(response.toString(),response.has("error"));return response.getJSONObject("result");}
    private void waitStage(String id,String stage)throws Exception{long deadline=System.currentTimeMillis()+20000;while(System.currentTimeMillis()<deadline&&!TransferEngine.get(id).optString("stage").equals(stage)){assertNotEquals(TransferEngine.get(id).toString(),"failed",TransferEngine.get(id).optString("stage"));Thread.sleep(100);}assertEquals(TransferEngine.get(id).toString(),stage,TransferEngine.get(id).optString("stage"));}
    private byte[] read(File file)throws Exception{try(InputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
    @Test public void nativeFingerprintsAndReceiptRecoveryMatchRealServer()throws Exception{
        assertTrue(android.os.Build.VERSION.SDK_INT>=36);instrumentation=InstrumentationRegistry.getInstrumentation();context=instrumentation.getTargetContext();TransferEngine.initialize(context);String endpoint=InstrumentationRegistry.getArguments().getString("backend");assertTrue(AccountIdentity.allowedBackend(endpoint));context.startActivity(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));long deadline=System.currentTimeMillis()+40000;boolean[] ready={false};while(System.currentTimeMillis()<deadline&&!ready[0]){instrumentation.runOnMainSync(()->{for(android.app.Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof MainActivity){view=((MainActivity)a).getBridge().getWebView();view.evaluateJavascript("!!window.TimehutTransfers",v->ready[0]="true".equals(v));}});Thread.sleep(100);}assertTrue(ready[0]);
        JSONObject profile=success("accountSignIn",new JSONObject().put("backend",endpoint).put("username","fixture-alpha").put("password","artificial-native-root-secret"));String owner=profile.getJSONObject("user").getString("id"),album=success("accountRequest",new JSONObject().put("path","/api/accounts/albums")).getJSONArray("albums").getJSONObject(0).getString("id");
        byte[] png=Base64.decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jR1sAAAAASUVORK5CYII=",Base64.DEFAULT);JSONObject task=TransferEngine.newRecord("upload","native-root-原檔.png","photo");String id=task.getString("id");File source=TransferEngine.file(id+"-source");try(FileOutputStream out=new FileOutputStream(source)){out.write(png);}task.put("sourceReference",source.getAbsolutePath()).put("mimeType","image/png").put("byteSize",png.length).put("stage","queued").put("tags","synthetic-root-server-only");TransferEngine.put(task);
        success("enqueueUpload",new JSONObject().put("id",id).put("endpoint",endpoint).put("albumId",album).put("tags","synthetic-root-server-only"));waitStage(id,"completed");JSONObject completed=TransferEngine.get(id);String receipt=completed.getString("serverReceiptId"),photo=completed.getString("flickrPhotoId");assertTrue(completed.getString("contentSha256").matches("[a-f0-9]{64}"));assertTrue(completed.getString("metadataSha256").matches("[a-f0-9]{64}"));JSONObject admitted=success("accountRequest",new JSONObject().put("path","/api/uploads/admission/"+id));assertEquals(receipt,admitted.getString("localId"));assertEquals("completed",admitted.getString("status"));
        JSONObject downloaded=success("enqueueDownload",new JSONObject().put("url",endpoint+"/api/photo/"+photo+"/image?size=o").put("filename","native-root-原檔.jpg").put("mediaType","photo"));String downId=downloaded.getString("id");TransferEngine.change(downId,"tags","synthetic-root-server-only");waitStage(downId,"file_ready");JSONObject down=TransferEngine.get(downId);assertEquals("native-root-原檔.png",down.getString("filename"));assertArrayEquals(png,read(new File(down.getString("destinationReference"))));
        // Only this newly-created synthetic source is removed, then restored exactly.
        assertArrayEquals(png,read(source));assertTrue(source.delete());try{TransferEngine.change(id,"serverReceiptId","");TransferEngine.change(id,"stage","queued");TransferEngine.resume(id);assertFalse(TransferEngine.run(id,TransferEngine.route(context.getSystemService(ConnectivityManager.class).getActiveNetwork())));assertEquals("completed",TransferEngine.get(id).getString("stage"));assertEquals(receipt,TransferEngine.get(id).getString("serverReceiptId"));}finally{if(!source.exists())try(FileOutputStream out=new FileOutputStream(source)){out.write(png);}else assertArrayEquals(png,read(source));}
        success("accountSignIn",new JSONObject().put("backend",endpoint).put("username","fixture-bravo").put("password","artificial-native-root-secret"));assertEquals(0,success("list",new JSONObject()).getJSONArray("tasks").length());assertTrue(call("accountRequest",new JSONObject().put("path","/api/album/"+album+"/photos")).has("error"));assertEquals("not_found",success("accountRequest",new JSONObject().put("path","/api/uploads/admission/"+id)).getString("admissionStatus"));assertArrayEquals(png,read(source));
        JSONObject report=new JSONObject().put("status","PASS_NATIVE_TO_ACTUAL_SERVER_UPLOAD_JOURNAL").put("sdk",android.os.Build.VERSION.SDK_INT).put("owner",owner).put("uploadId",id).put("downloadId",downId).put("receiptId",receipt).put("flickrPhotoId",photo).put("contentSha256",completed.getString("contentSha256")).put("metadataSha256",completed.getString("metadataSha256")).put("unicodeFilenameAndTagsMatchServer",true).put("nativeUIDTUploadAndDownload",true).put("exactOriginalAndPNGExtension",true).put("lostReceiptWithMissingSourceRecoveredWithoutPost",true).put("sourceRestoredExactly",true).put("otherOwnerAdmissionAndAlbumDenied",true).put("providerRequests",0).put("physicalPhone",false).put("appSwitchLockProof",false);
        try(FileOutputStream out=new FileOutputStream(new File(context.getFilesDir(),"server-integration-qa-report.json"))){out.write(report.toString(2).getBytes(StandardCharsets.UTF_8));}
    }
}
